FormulaFieldDefinitions.FormulaFieldDefinition:
WhilePrintingRecords;
NumberVar AcBal;
AcBal := AcBal + {@CrRs} - {@DrRs};
AcBal;

WhilePrintingRecords;
NumberVar BalAmt;
BalAmt := BalAmt + Sum ({@CrRs}, {@VchGroup})-Sum ({@DrRs}, {@VchGroup});
BalAmt;

WhilePrintingRecords;
NumberVar BalGold;
BalGold := BalGold + Sum ({@CrGold}, {@VchGroup})-Sum ({@DrGold}, {@VchGroup});
BalGold;

WhilePrintingRecords;
NumberVar BalSilver;
BalSilver := BalSilver + Sum ({@CrSilver}, {@VchGroup})-Sum ({@DrSilver}, {@VchGroup});
BalSilver;

WhilePrintingRecords;
NumberVar GoldBal;
GoldBal := GoldBal + {@CrGold} - {@DrGold};
GoldBal;

//EvaluateAfter ({@BalAmt});
WhilePrintingRecords;
NumberVar BalAmt;
if BalAmt >= 0 then
  'Cr'
else if BalAmt < 0 then
  'Dr';

WhilePrintingRecords;
NumberVar SilverBal;
SilverBal := SilverBal + {@CrSilver} - {@DrSilver};
SilverBal;
